import React from 'react';
import LangHelper from '@jsroot/lib/langHelper';
import { UpdateMonitoredPlayerCode } from '../lib/constants';

export default class MessageHelper {
    static MsgColors = {
        [UpdateMonitoredPlayerCode.Success]: {
            content: 'msg-success',
            icon: 'icon-tick'
        },
        [UpdateMonitoredPlayerCode.InvalidSystemId]: {
            content: 'msg-error',
            icon: 'icon-warning'
        },
        [UpdateMonitoredPlayerCode.InvalidExternalId]: {
            content: 'msg-error',
            icon: 'icon-warning'
        },
        [UpdateMonitoredPlayerCode.ExistingInList]: {
            content: 'msg-error',
            icon: 'icon-warning'
        },
        [UpdateMonitoredPlayerCode.InvalidWinningThreshold]: {
            content: 'msg-error',
            icon: 'icon-warning'
        },
        [UpdateMonitoredPlayerCode.InvalidAccount]: {
            content: 'msg-error',
            icon: 'icon-warning'
        }
    }

    static GetMsgUpdateMonitoredPlayer = {
        // singleUpdate: {
        //     [UpdateVIPStatusCode.Success]: _ => LangHelper.getSingleResource('SuccessUpdateVipStatusSingle'),

        //     [UpdateVIPStatusCode.InvalidSystemId]: data => LangHelper.getSingleResource('InvalidPlayerUpdateVipStatusSingle')
        //         .replace('{0}', data.ids),

        //     [UpdateVIPStatusCode.NoChangeBySystemId]: (_, isUpdateVip) => (isUpdateVip ? LangHelper.getSingleResource('AlreadyUpdateVipStatusSingle') : LangHelper.getSingleResource('AlreadyUpdateNotVipStatusSingle')),

        //     [UpdateVIPStatusCode.NoChangeByBAStatus]: () => LangHelper.getSingleResource('BAPlayerNoUpdateVIPSingle'),

        //     [UpdateVIPStatusCode.Avoid]: data => LangHelper.getSingleResource('RetractedPlayerUpdateVipStatusSingle')
        //         .replace('{0}', data.ids)
        // },
        multipleUpdate: {
            [UpdateMonitoredPlayerCode.Success]: data => LangHelper.getSingleResource('SuccessUpdateMonitoredPlayer')
                .replace('{0}', data.numberOfError),

            [UpdateMonitoredPlayerCode.InvalidSystemId]: data => LangHelper.getSingleResource('InvalidUpdateMonitoredPlayerBySystemId')
                .replace('{0}', data.numberOfError)
                .replace('{1}', data.systemId),

            [UpdateMonitoredPlayerCode.InvalidExternalId]: data => LangHelper.getSingleResource('InvalidUpdateMonitoredPlayerByExternalId')
                .replace('{0}', data.numberOfError)
                .replace('{1}', data.externalId),

            [UpdateMonitoredPlayerCode.InvalidWinningThreshold]: data => LangHelper.getSingleResource('InvalidPlayerUpdateWinningThreshold')
                .replace('{0}', data.numberOfError)
                .replace('{1}', data.externalId || data.systemId)
        }
    }

    static GetListMsgUpdateMonitoredPlayer = msgResults => {
        if(!msgResults.length) {
            msgResults = [msgResults]
        }
        return msgResults.map(_ => {
            const code = _.errorCode;
            const msgColor = MessageHelper.MsgColors[code];
            return (<p className="msg-result">
                <i className={`icon ${msgColor.icon}`}></i>
                <span className={msgColor.content}>{MessageHelper.GetMsgUpdateMonitoredPlayer['multipleUpdate'][code](_)}</span>
            </p>)
        })
    }
}

